from collections import defaultdict

def shortest_path(graph, source, target):
    # Preprocessing the graph to support bidirectional search
    forward_graph = defaultdict(list)
    reverse_graph = defaultdict(list)
    for node, edges in graph.items():
        for neighbor, weight in edges:
            forward_graph[node].append((neighbor, weight))
            reverse_graph[neighbor].append((node, weight))

    def dijkstra(graph, start, end):
        # Priority queue to store the vertices to expand and their distances
        queue = [(0, start)]
        visited = {start: 0}
        previous = {}

        while queue:
            current_distance, current_vertex = heappop(queue)

            if current_vertex == end:
                path = []
                while current_vertex in previous:
                    path.append(current_vertex)
                    current_vertex = previous[current_vertex]
                path.reverse()
                return path

            for neighbor, weight in graph[current_vertex]:
                distance = current_distance + weight

                if neighbor not in visited or distance < visited[neighbor]:
                    visited[neighbor] = distance
                    previous[neighbor] = current_vertex
                    heappush(queue, (distance, neighbor))

        return None

    # Run Dijkstra's algorithm twice: from source to target and from target to source
    forward_path = dijkstra(forward_graph, source, target)
    reverse_path = dijkstra(reverse_graph, target, source)

    # If there is a path in both directions, combine them
    if forward_path and reverse_path:
        path = forward_path + reverse_path[1:]  # Add the path from source to target
        return (sum(weight for node, weight in forward_path), path)

    # If no path is found in either direction, return infinity and None
    return float("inf"), None
